// vm — a register-machine bytecode interpreter: the core loop every VM / DSL / calculator
// runs (fetch → decode → dispatch → execute over a register file). A deterministic instruction
// stream is generated by the shared LCG and executed in order; the final register state reduces
// to a checksum. A real interpreter workload — dispatch-heavy, not a teaching algorithm — and
// byte-identical across every language.
public class Main {
    static final long MOD = 1000000007L;
    static final int NREG = 8;

    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("usage: vm <n>");
            System.exit(1);
        }
        long n = Long.parseLong(args[0]);
        long seed = 42;
        long[] regs = new long[NREG];
        for (int i = 0; i < NREG; i++) regs[i] = i + 1;          // seed the register file
        for (long k = 0; k < n; k++) {
            seed = (seed * 1103515245L + 12345) % 2147483648L;   // fetch
            long instr = (seed >> 8) & 0x7fffff;                 // decode
            int op = (int) (instr % 8);
            int dst = (int) ((instr / 8) % NREG);
            int a = (int) ((instr / 64) % NREG);
            long imm = (instr / 512) % 251;
            switch (op) {                                        // dispatch → execute
                case 0: regs[dst] = imm; break;                              // LOADI
                case 1: regs[dst] = (regs[dst] + regs[a]) % MOD; break;      // ADD
                case 2: regs[dst] = (regs[dst] + MOD - regs[a]) % MOD; break;// SUB
                case 3: regs[dst] = (regs[dst] * regs[a] + 1) % MOD; break;  // MULADD
                case 4: regs[dst] = (regs[dst] + imm) % MOD; break;         // ADDI
                case 5: regs[dst] = (regs[dst] * (imm + 1)) % MOD; break;    // MULI
                case 6: regs[dst] = regs[a]; break;                          // MOV
                case 7: regs[dst] = (regs[dst] + regs[a] + imm) % MOD; break;// MIX
            }
        }
        long checksum = 0;
        for (int i = 0; i < NREG; i++)
            checksum = (checksum * 31 + regs[i]) & 268435455;
        System.out.println(checksum);
    }
}
